INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0047', 647, 'VNYLT', 'VNYLT - File 1 (Đợt 1)', 'Which type of logistics is within NGOs’ interest?', '[{"key": "A", "text": "Green logistics"}, {"key": "B", "text": "Humanitarian logistics (Emergency logistics)"}, {"key": "C", "text": "Military logistics"}, {"key": "D", "text": "Business logistics RAM Logistics (see also Logistic engineering) combines both business logistics and military logistics since it is concerned with highly complicated technological systems for which Reliability, Availability and Maintainability are essential, ex: weapon systems and military supercomputers. ( RAM Logistics (xem thêm Kỹ thuật hậu cần) kết hợp ca hậu cần kinh doanh và hậu cần quân sự vì nó liên quan đến các hệ thống công nghệ rất phức tạp, trong đó Độ tin cậy, Tính kha dụng và Bao trì là rất cần thiết, ví dụ: hệ thống vũ khí và siêu máy tính quân sự )"}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0048', 648, 'VNYLT', 'VNYLT - File 1 (Đợt 1)', 'Rice is exported from VN to China. The price of goods agreed between seller and buyer is USD 60 MT/FOB Sai Gon Port with the exchange rate of 20000 VND/USD. The total export volume is 2000 MT and the commodity price will change arccoding to the fluctuation of the exchange rate. When the exchange rate changed to 21000 VND/USD , which of the following conclusions is correct?', '[{"key": "A", "text": "The buyer gained profit because of the VND 120,000,000 reducing he actually paid"}, {"key": "B", "text": "The seller occurred a loss because of the 60,000,000 reducing he actually received"}, {"key": "C", "text": "The seller gained profit because of the 120,000,000 increasing he actually received"}, {"key": "D", "text": "The buyer was not affected by the exchange rate fluctuation Gạo được xuất khẩu từ VN sang Trung Quốc. Giá hàng hóa được thỏa thuận giữa người bán và người mua là 60 USD / FOB Cang Sài Gòn với tỷ giá 20000 đồng / USD. Tổng khối lượng xuất khẩu là 2000 tấn và giá hàng hóa sẽ thay đổi mã hóa theo sự biến động của tỷ giá hối đoái. Khi tỷ giá hối đoái đổi thành 21000 đồng / USD, kết luận nào sau đây là đúng? Người mua có lãi vì giam 120.000.000 đồng mà anh ta thực sự đã tra Người bán đã thua lỗ vì giam 60.000.000 mà anh ta thực sự nhận được Người bán đã kiếm được lợi nhuận nhờ số tiền tǎng thêm 120.000.000 mà anh ta thực sự nhận được Người mua không bị anh hưởng bởi biến động tỷ giá hối đoái"}]'::jsonb, 'C') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0049', 649, 'VNYLT', 'VNYLT - File 1 (Đợt 1)', 'What is true about ABC analysis', '[{"key": "A", "text": "Class B means patterns of fluctuating demand"}, {"key": "B", "text": "It tell us about the demand of patterns of a product"}, {"key": "C", "text": "Class A means patterns of constant, non-changing demand"}, {"key": "D", "text": "Class C means patterns of low annual dollar volume"}]'::jsonb, 'D') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
