INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0176', 776, 'VNYLT', 'VNYLT - File 2 (Đợt 4)', 'Mối quan hệ giữa chiến lược dịch vụ khách hàng với chiến lược dịch vụ logistics?', '[{"key": "A", "text": "Chiến lược logistics là một bộ phận của chiến lược dịch vụ khách hàng"}, {"key": "B", "text": "Chiến lược dịch vụ khách hàng là một bộ phận của chiến lược logistics"}, {"key": "C", "text": "Chiến lược dịch vụ khách hàng và chiến lược logistics hoàn toàn không có mối quan hệ"}, {"key": "D", "text": "Chiến lược dịch vụ khách hàng và chiến lược logistics tồn tại song song"}]'::jsonb, 'A') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
