INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0229', 829, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Công ty cổ phần Logistics U&I là một doanh nghiệp đứng đầu trong lĩnh vực Logistics. Tổng số lưuọng tờ khai mà U&I Logistics đã làm dịch vụ trong năm 2020 là bao nhiêu?', '[{"key": "A", "text": "Khoảng 36000"}, {"key": "B", "text": "Khoảng 56000"}, {"key": "C", "text": "Khoảng 76000"}, {"key": "D", "text": "Khoảng 96000"}]'::jsonb, 'D') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0230', 830, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Hệ thống phân phối kiểu last mile là hệ thống:', '[{"key": "A", "text": "Giao hàng trực tiếp từ nhà cung cấp (đại lý, nhà phân phối) đến tận tay người tiêu dùng riêng lẻ."}, {"key": "B", "text": "Kết hợp giao hàng trực tiếp từ nhà cung cấp đến nhiều tiêu dùng hay đại lý cho 1 chuyến hàng"}, {"key": "C", "text": "Giao hàng trực tiếp từ nhà cung cấp đến tận tay cả đại lý và nhà phân phối."}, {"key": "D", "text": "Kết hợp giao hàng trực tiếp từ nhà cung cấp đến nhiều nhà phân phối hay đại lý cho 1 chuyến hàng."}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0231', 831, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Theo loại hình doanh nghiệp, 3PL không bao gồm:', '[{"key": "A", "text": "Các doanh nghiệp kinh doanh vận tải"}, {"key": "B", "text": "Các doanh nghiệp kinh doanh kho hàng và trung tâm phân phối"}, {"key": "C", "text": "Các doanh nghiệp công nghệ thông tin"}, {"key": "D", "text": "Các doanh nghiệp kinh doanh thiết bị làm hàng"}]'::jsonb, 'C') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0232', 832, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'What is wrong about customs checking? Kiểm tra hải quan có gì sai?', '[{"key": "A", "text": "Do hải quan cung cấp."}, {"key": "B", "text": "Kiểm tra hàng hóa."}, {"key": "C", "text": "Chỉ kiểm tra, giám định hàng hóa không phải phương tiện vận chuyển."}, {"key": "D", "text": "Kiểm tra hồ sơ và các tài liệu liên quan khác."}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0233', 833, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Theo chiến lược phát triển dịch vụ vận tải đến năm 2020, định hướng đến năm 2030 (ban hành tại Quyết định 318QĐ-TTg ngày 432014), thị trường vận tải nội địa sẽ được tái cơ cấu theo hướng nào sau đây?', '[{"key": "A", "text": "Tăng thị phần vận tải thủy nội địa."}, {"key": "B", "text": "Tăng thị phần vận tải đường sắt và đường thủy nội địa."}, {"key": "C", "text": "Tăng thị phần vận tải đường hàng không."}, {"key": "D", "text": "Duy trì cơ cấu thị phần vận tải như hiện nay."}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0234', 834, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Chức năng nào của hệ thống TT Logistics nhằm vào việc đo lường hoạt động nghiệp vụ và báo cáo?', '[{"key": "A", "text": "Chức năng tác nghiệp"}, {"key": "B", "text": "Chức năng kiểm soát"}, {"key": "C", "text": "Chức năng phân tích và ra quyết định"}, {"key": "D", "text": "Chức năng hoạch định chiến lược"}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0235', 835, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Đường sắt có thể:', '[{"key": "A", "text": "Tiết kiệm năng lượng hơn hầu hết các loại hình khác."}, {"key": "B", "text": "Nhiều khả năng chuyên chở hàng hóa hơn các loại hình khác"}, {"key": "C", "text": "Không tiết kiệm năng lượng như hầu hết các loại hình khác"}, {"key": "D", "text": "Tất cả đáp án trên đều đúng"}]'::jsonb, 'A') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0236', 836, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Which of the following features is in ‘codes for sustainable procurement’? : Tính năng nào sau đây nằm trong "mã cho mua sắm bền vững"?', '[{"key": "A", "text": "Cam kết xem xét tác động môi trường toàn bộ vòng đời của một sản phẩm."}, {"key": "B", "text": "Cam kết giảm cơ sở nhà cung cấp."}, {"key": "C", "text": "Cam kết loại bỏ đấu thầu đối với các hợp đồng có giá trị lớn."}, {"key": "D", "text": "Cam kết cung cấp bảng phân tích chi phí đầy đủ về giá bán lẻ cho người tiêu dùng."}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0237', 837, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'The sequence of typical manufacturing supply chain is:', '[{"key": "A", "text": "Storage – supplier – Manufacturing – Storege – Distributor – Retailer – Customs."}, {"key": "B", "text": "Supplier – Storage – Manufacturing – Storage – Distributor – Retailer – Customs."}, {"key": "C", "text": "Supplier – Storage – Manufacturing – Distributor – Storage – Retailer – Customs."}, {"key": "D", "text": "Supplier – Storage – Manufacturing – Storage – Retailer – Distributor – Customs."}]'::jsonb, 'B') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0238', 838, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Fill the blank: … is the process of procuring the proper requirement, at the necessary time, for the lowest possible cost from a reliable source. :… Là quá trình mua sắm theo yêu cầu thích hợp, vào thời điểm cần thiết, với chi phí thấp nhất có thể từ một nguồn đáng tin cậy.', '[{"key": "A", "text": "Mua hàng"}, {"key": "B", "text": "Tất cả câu trả lời đều đúng"}, {"key": "C", "text": "Tìm nguồn cung ứng"}, {"key": "D", "text": "Gia công phần mềm"}]'::jsonb, 'C') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
