INSERT INTO questions (ma_cau_hoi, stt, muc_do, ten_chu_de, cau_hoi, options, correct_answer) VALUES ('VNYLT_0248', 848, 'VNYLT', 'VNYLT - File 2 (Đợt 5)', 'Clean B/L là vận đơn:', '[{"key": "A", "text": "Có ghi chú ‘clean’ của người chuyên chở trên B/L"}, {"key": "B", "text": "Không có bất kì ghi chú nào của người chuyên chở"}, {"key": "C", "text": "Không có bất kì ghi chú xấu nào về hàng hóa và bao bì hàng hóa của người chuyên chở"}, {"key": "D", "text": "Trên bề mặt B/L không bị tẩy xóa"}]'::jsonb, 'C') ON CONFLICT (ma_cau_hoi) DO UPDATE SET cau_hoi = EXCLUDED.cau_hoi, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
